import type { AppIcon } from "apps";

// Generated by scripts/icon.ts from Simple Icons (CC0) "clerk".
export const icons: readonly AppIcon[] = [
  {
    "src": "data:image/svg+xml;base64,",
    "mimeType": "image/svg+xml",
    "theme": "light"
  },
  {
    "src": "data:image/svg+xml;base64,",
    "mimeType": "image/svg+xml",
    "theme": "dark"
  }
];

import {
  accountRouter,
  decodeJson,
  defineApp,
  defineProvider,
  object,
  router,
  secrets,
  string,
  withApprovals,
} from "apps";
import { always } from "apps/operations/approval";
import { liveOpenapiRouter } from "apps/openapi";
import { icons } from "./icon.js";
import { options } from "./openapi.js";
import { clerkSignIn, signedInRouter } from "./mcp.js";

const clerk = defineProvider({
  name: "Clerk",
  hosts: ["api.clerk.com"],
  auth: {
    apiKey: secrets({
      label: "Secret key (sk_test_... or sk_live_...)",
      fields: object({ token: string({ minLength: 1 }) }),
    }),
  },
  async health({ account, fetch, signal }) {
    const response = await fetch("https://api.clerk.com/v1/users/count", {
      signal,
      headers: { Authorization: `Bearer ${account.fields.token}` },
    });
    await decodeJson(response, object({}));
  },
});

export default defineApp(
  { user: { accounts: { signIn: clerkSignIn.many(), clerk: clerk.many() } }, icons },
  async ({ user, cache, fetch, signal }) => ({
    tools: router(
      await accountRouter(
        [
          ...(user?.accounts.clerk ?? []).map((account) => ({
            id: account.id,
            discover: () => withApprovals(
              liveOpenapiRouter({ ...options, cache, fetch, signal, account }),
              (tool) => tool.kind === "mutation" ? always() : undefined,
            ),
          })),
          ...(user?.accounts.signIn ?? []).map((account) => ({
            id: account.id,
            discover: () => signedInRouter(account, { cache, signal }),
          })),
        ],
        (account) => account.discover(),
        { signal },
      ),
      {
        title: "Clerk",
        description: "Manage Clerk applications, users, organizations, domains and instance settings.",
        icons,
      },
    ),
  }),
);

import type { OpenapiToolNamesOptions } from "apps/openapi";

// Clerk's versioned Backend API spec; bump the dated file to adopt a newer API version.
export const options = {
  source: { url: "https://raw.githubusercontent.com/clerk/openapi-specs/main/bapi/2026-05-12.yml" },
  allowedOrigin: "https://api.clerk.com",
  securitySchemes: { bearerAuth: { type: "http", scheme: "bearer" } },
  methods: { apiKey: [{ scheme: "bearerAuth", field: "token", part: "value", prefix: "" }] },
  oauth: [],
} satisfies OpenapiToolNamesOptions;

{
  "name": "@executor.sh/clerk",
  "description": "Manage Clerk users, organizations, sessions, invitations, domains, JWT templates and instance settings through the Backend API.",
  "private": true,
  "type": "module",
  "dependencies": {
    "apps": "0.0.1-beta.104-basalt.16",
    "@modelcontextprotocol/sdk": "1.32.1"
  },
  "executor": {
    "title": "Clerk"
  }
}

import { defineProvider, oauth2, withApprovals, type AccountOf, type AppCache } from "apps";
import { mcpHealth, mcpRouter } from "apps/mcp";
import { always } from "apps/operations/approval";

const url = "https://mcp.clerk.com/mcp";
const headers = (account: { fields: { access_token: string } }) => ({
  Authorization: `Bearer ${account.fields.access_token}`,
});

// A separate provider preserves existing API-key accounts and their links.
export const clerkSignIn = defineProvider({
  name: "Clerk",
  hosts: ["mcp.clerk.com"],
  auth: { oauth: oauth2({ discover: url, scopes: ["user:org:read","applications:read","applications:manage","users:read","users:manage","application_domains:read","application_domains:manage"] }) },
  health: (check) => mcpHealth(check, { url, headers: headers(check.account) }),
});

export const signedInRouter = async (
  account: AccountOf<typeof clerkSignIn>,
  context: { cache: AppCache; signal: AbortSignal },
) => withApprovals(
  await mcpRouter({ url, account, headers: headers(account), ...context }),
  (tool) => tool.kind === "mutation" ? always() : undefined,
);
